/* Chart presentation, navigation and transition lists; no natal formula changes. */
(()=>{'use strict';const $=id=>document.getElementById(id);let busy=false,transitionDialog;
const decorate=window.KPQuickTools?.decorate;if(decorate)window.KPQuickTools.decorate=function(button,tab,name){decorate(button,tab,name);const label=button.querySelector('.kp-quick-label');if(label)label.textContent=name;};
function menu(){for(const button of document.querySelectorAll('.kp-quick-tools button[data-quick-function]')){const title=button.getAttribute('aria-label');const label=button.querySelector('.kp-quick-label');if(label&&title&&label.textContent!==title)label.textContent=title;}document.querySelector('.kp-quick-tools')?.setAttribute('aria-label','KP Master menu');}
function legend(){for(const host of document.querySelectorAll('#kundali-north,#home-kundali')){const svg=host.querySelector('.north9-chart svg')||host.querySelector('svg');if(!svg)continue;const entries=[...svg.querySelectorAll('text[data-longitude]')];if(!entries.length)continue;let details=host.parentElement.querySelector(':scope > .kp-chart-readable');if(!details){details=document.createElement('details');details.className='kp-chart-readable';details.innerHTML='<summary>Chart positions · readable list</summary><div></div>';host.after(details);}const content=entries.map(n=>{const id=n.dataset.planet||n.dataset.cusp||n.dataset.kpOriginalLabel||n.textContent;return id+' · '+n.dataset.longitude;}).join('|');if(details.dataset.signature===content)continue;details.dataset.signature=content;details.lastElementChild.replaceChildren(...entries.map(n=>{const line=document.createElement('p');const arc=Number(n.dataset.longitude),degree=Number.isFinite(arc)?(arc/3600).toFixed(5)+'°':'';line.textContent=(n.dataset.kpOriginalLabel||n.textContent)+' · '+degree;return line;}));}}
function colours(){const pane=$('settings-pane-astrologer');if(!pane||$('kp-chart-colours-link'))return;const box=document.createElement('section');box.id='kp-chart-colours-link';box.innerHTML='<h4>Chart colours and text</h4><p>Choose planet colours, chart font size and bold text.</p>';for(const [name,tab]of [['Planet colours','themes'],['Chart font size','display']]){const b=document.createElement('button');b.type='button';b.textContent=name;b.onclick=()=>{$('settings-tab-'+tab)?.click();const field=$(tab==='themes'?'setting-planetColorSu':'setting-fontSize');field?.scrollIntoView({block:'center'});field?.focus();};box.append(b);}const grid=document.createElement('div');grid.className='kp-astro-chart-colours';for(const id of ['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke']){const original=$('setting-planetColor'+id);if(!original)continue;const label=document.createElement('label');label.textContent=(window.KPDisplay?.names[id]||id)+' colour';const input=document.createElement('input');input.type='color';input.value=original.value;input.id='kp-astro-colour-'+id;input.addEventListener('input',()=>{original.value=input.value;original.dispatchEvent(new Event('input',{bubbles:true}));original.dispatchEvent(new Event('change',{bubbles:true}));});original.addEventListener('input',()=>input.value=original.value);label.append(input);grid.append(label);}box.append(grid);pane.append(box);$('settings-tab-astrologer')?.addEventListener('click',()=>{for(const id of ['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke']){const n=$('kp-astro-colour-'+id),source=$('setting-planetColor'+id);if(n&&source)n.value=source.value;}});}
function printable(title,body){const w=window.open('','_blank');if(!w)return;w.document.open();w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+title+'</title><style>@page{size:A4;margin:12mm}body{font:12px Arial;color:#17364c;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #a8b8c5;padding:7px;overflow-wrap:anywhere}thead{display:table-header-group}tr{break-inside:avoid}button{padding:10px}@media print{button{display:none}}</style></head><body><button onclick="print()">Print / Save PDF</button><h2>'+title+'</h2>'+body+'</body></html>');w.document.close();}
async function transitions(){if(!transitionDialog){transitionDialog=document.createElement('dialog');transitionDialog.className='kp-cusp-dialog';transitionDialog.innerHTML='<h2>Ascendant / Moon transitions</h2><div class="kp-transition-tools"><label>Planet <select data-body><option value="As">Ascendant · next 24 hours</option><option value="Mo">Moon · next 30 days</option></select></label><label>Combination <select data-level><option value="star">Nakshatra</option><option value="sub">Sub lord</option></select></label><button data-find>Find transitions</button><button data-print>Preview / Print / PDF</button><button data-close>Close</button></div><p data-status>Starting at the current moment, using the native chart location.</p><div data-results></div>';document.body.append(transitionDialog);transitionDialog.querySelector('[data-close]').onclick=()=>transitionDialog.close();transitionDialog.querySelector('[data-find]').onclick=find;transitionDialog.querySelector('[data-print]').onclick=()=>printable('Ascendant / Moon transitions',transitionDialog.querySelector('[data-results]').innerHTML);}
transitionDialog.showModal();}
async function find(){if(busy)return;busy=true;const d=transitionDialog,button=d.querySelector('[data-find]'),status=d.querySelector('[data-status]');button.disabled=true;try{const planet=d.querySelector('[data-body]').value,level=d.querySelector('[data-level]').value,start=new Date(),end=new Date(start.getTime()+(planet==='As'?1:30)*86400000),native=KPHorary.nativeMoment(),tracks=[];const lords=['Ke','Ve','Su','Mo','Ma','Ra','Ju','Sa','Me'];for(let n=0;n<27;n++)for(const lord of level==='sub'?lords:[null])tracks.push({id:n+':'+lord,planet,label:'',levels:[level],test:p=>p.nakIndex===n&&(!lord||p.sl===lord)});const rows=await KPTransit.scan({start,end,tracks,location:native,onProgress:p=>status.textContent='Searching… '+Math.round(p*100)+'%'}),offset=KPHomeDasha.getData().timeZoneHours*3600000;const table=document.createElement('table');table.className='kp-feature-table';table.innerHTML='<thead><tr><th>Combination · sign / star / sub</th><th>Entry · local time</th><th>Longitude</th></tr></thead><tbody></tbody>';for(const row of rows.filter(r=>!r.startClipped)){const date=new Date(Date.parse(row.start)+1500),lon=planet==='As'?KPTransitHouses.ascendant(date,native.latitude,native.longitude):KPEphemeris.longitude(date,planet),p=KPDisplay.longitudeDetails(lon*3600),tr=document.createElement('tr');for(const value of [p.sgl+' / '+p.stl+' / '+p.sl,new Date(Date.parse(row.start)+offset).toISOString().replace('T',' ').slice(0,19),lon.toFixed(6)+'°']){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.tBodies[0].append(tr);}d.querySelector('[data-results]').replaceChildren(table);status.textContent=table.tBodies[0].rows.length+' transitions · local chart time · boundary precision 1 second.';}catch(e){status.textContent=e.message;}finally{busy=false;button.disabled=false;}}
function init(){menu();colours();const bar=document.querySelector('#south9 .kundali-toolbar');if(bar){const b=document.createElement('button');b.textContent='Ascendant / Moon transitions';b.onclick=transitions;bar.after(b);}const observer=new MutationObserver(()=>requestAnimationFrame(legend));for(const id of ['kundali-north','home-kundali'])if($(id))observer.observe($(id),{childList:true,subtree:true});legend();}
window.KPChartWorkspace=Object.freeze({transitions,printable});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,100));else init();})();
